<?php
namespace App\Tests\Attachments;
use App\Attachments\AttachmentStorageBroker;
use PHPUnit\Framework\TestCase;
final class AttachmentStorageBrokerTest extends TestCase
{
 private string $base;private string $secret;private AttachmentStorageBroker $broker;
 protected function setUp():void {$this->base=sys_get_temp_dir().'/ciw-broker-'.bin2hex(random_bytes(8));mkdir($this->base);mkdir($this->base.'/docs');mkdir($this->base.'/private');$this->secret=random_bytes(32);$this->broker=new AttachmentStorageBroker($this->base.'/docs',$this->base.'/private',$this->secret);file_put_contents($this->base.'/docs/existing.pdf',"%PDF-1.4\nexisting\n");}
 protected function tearDown():void {if(!isset($this->base)||!is_dir($this->base))return;$root=realpath($this->base);foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST)as$f){$p=$f->getPathname();self::assertStringStartsWith($root.DIRECTORY_SEPARATOR,$p);if($f->isDir()&&!$f->isLink())rmdir($p);else unlink($p);}rmdir($root);}
 private function envelope(string $op,array $extra=[]):array {return array_replace(['v'=>1,'op'=>$op,'requestId'=>bin2hex(random_bytes(16)),'timestamp'=>time(),'nonce'=>bin2hex(random_bytes(16)),'owner'=>str_repeat('a',64)],$extra);}
 private function sign(array $e):array {$encoded=base64_encode(json_encode($e,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return [$encoded,hash_hmac('sha256',$encoded,$this->secret)];}
 private function call(array $e,string $bytes=''):array {[$h,$s]=$this->sign($e);$stream=fopen('php://temp','w+b');fwrite($stream,$bytes);rewind($stream);try{return $this->broker->execute($h,$s,$stream);}finally{fclose($stream);}}
 private function put(string $bytes="%PDF-1.4\ntest\n",array $extra=[]):array {$e=$this->envelope('put',$extra+['fileName'=>'teste.pdf','size'=>strlen($bytes),'sha256'=>hash('sha256',$bytes)]);return [$this->call($e,$bytes),$e];}
 private function rejected(callable $work,string $message=''):void {$error=null;try{$work();}catch(\RuntimeException $e){$error=$e;}self::assertNotNull($error,'Expected storage rejection');if($message!=='')self::assertStringContainsString($message,$error->getMessage());}
 public function testPutIsImmutableAndRetryOfSameOperationIsIdempotent():void {[$one,$e]=$this->put();$e['nonce']=bin2hex(random_bytes(16));$two=$this->call($e,"%PDF-1.4\ntest\n");self::assertSame($one['reference'],$two['reference']);self::assertSame($one['sha256'],$two['sha256']);self::assertCount(2,glob($this->base.'/docs/*'));self::assertSame("%PDF-1.4\nexisting\n",file_get_contents($this->base.'/docs/existing.pdf'));}
 public function testReplayOrWrongSignatureIsRejectedBeforeWriting():void {$e=$this->envelope('health');[$h,$s]=$this->sign($e);self::assertTrue($this->broker->execute($h,$s,null)['success']);$this->rejected(fn()=>$this->broker->execute($h,$s,null),'replay');$this->expectException(\RuntimeException::class);$this->broker->execute($h,str_repeat('0',64),null);}
 public function testCommittedObjectCannotBeCompensatedOrOverwritten():void {[$o,$e]=$this->put();$this->call($this->envelope('commit',['requestId'=>$e['requestId']]));$this->rejected(fn()=>$this->call($this->envelope('abort',['requestId'=>$e['requestId']])),'committed');self::assertFileExists($this->base.'/docs/'.$o['reference']);$e['nonce']=bin2hex(random_bytes(16));$e['sha256']=hash('sha256','%PDF-forged');$e['size']=strlen('%PDF-forged');$this->expectException(\RuntimeException::class);$this->call($e,'%PDF-forged');}
 public function testAbortCanOnlyRemoveOwnNewStagedObject():void {[$o,$e]=$this->put();$r=$this->call($this->envelope('abort',['requestId'=>$e['requestId']]));self::assertTrue($r['success']);self::assertFileDoesNotExist($this->base.'/docs/'.$o['reference']);self::assertFileExists($this->base.'/docs/existing.pdf');}
 public function testLegacyDownloadIsReadOnlyAndPathTraversalIsRejected():void {$before=hash_file('sha256',$this->base.'/docs/existing.pdf');$r=$this->call($this->envelope('get',['reference'=>'existing.pdf']));self::assertSame($before,$r['sha256']);self::assertSame(realpath($this->base.'/docs/existing.pdf'),$r['path']);self::assertSame($before,hash_file('sha256',$r['path']));foreach(['../existing.pdf','/etc/passwd','http://example.com/a.pdf','folder\\existing.pdf']as$ref){$this->rejected(fn()=>$this->call($this->envelope('get',['reference'=>$ref])),'reference');}}
 public function testShortOrWrongHashUploadHasNoDurableFile():void {foreach([['size'=>100],['sha256'=>str_repeat('f',64)]]as$extra){$this->rejected(fn()=>$this->put("%PDF-1.4\ntest\n",$extra));self::assertCount(1,glob($this->base.'/docs/*'));}}
 public function testOversizeAndForeignOwnerAreRejected():void {$this->rejected(fn()=>$this->put('%PDF-1.4',['size'=>20971521]),'size');[$o,$e]=$this->put();$this->expectException(\RuntimeException::class);$this->call($this->envelope('abort',['requestId'=>$e['requestId'],'owner'=>str_repeat('b',64)]));}
 public function testExpiredEnvelopeOrArbitraryFieldsAreRejected():void {foreach([['timestamp'=>time()-300],['root'=>'/tmp'],['op'=>'deleteLegacy']]as$extra){$this->rejected(fn()=>$this->call($this->envelope('health',$extra)));}self::assertCount(1,glob($this->base.'/docs/*'));}
 public function testCorruptedReceiptNeverBecomesANewUpload():void {[$o,$e]=$this->put();$path=$this->base.'/private/journal/'.$e['requestId'].'.json';file_put_contents($path,'{broken');$e['nonce']=bin2hex(random_bytes(16));$this->rejected(fn()=>$this->call($e,"%PDF-1.4\ntest\n"),'corrupted');self::assertSame('{broken',file_get_contents($path));self::assertSame($o['sha256'],hash_file('sha256',$this->base.'/docs/'.$o['reference']));}
 public function testHistoricalNamesDoNotUseTheNewUploadNamePolicy():void {file_put_contents($this->base.'/docs/.historico.pdf','legacy');$r=$this->call($this->envelope('get',['reference'=>'.historico.pdf']));self::assertSame(hash('sha256','legacy'),$r['sha256']);}
}
